package compiler

import (
	"encoding/hex"
	"fmt"
	"math/rand"
	"strings"
	"testing"

	evalorder "gosvm/examples/eval-order"
)

// Evaluation order against native Go: examples/eval-order (generated by
// examples/eval-order/gen) runs natively and as host-compiled C; output
// bytes, results, panics and each panic's log line must match for every
// vector. Calls in the examples write the operands of their own
// expressions, and traps race panicking calls, so any difference from gc's
// order shows. See docs/ERROR_CONTRACT.md#evaluation-order.

// evalOrderRun is the example run natively.
var evalOrderRun = evalorder.Run

func evalOrderSource(t *testing.T) []byte {
	return mustRead(t, "../../examples/eval-order/program.go")
}

// EvalOrderCases is the number of cases Run dispatches on.
func EvalOrderCases() int { return evalorder.GeneratedCasesForTest + evalorder.SpecialCasesForTest }

// evalOrderVectors gives every case perCase vectors: random values, then
// writers that panic, then random trap selections (an index out of range, a
// nil pointer or map, a zero divisor), with and without panicking writers.
func evalOrderVectors(seed int64, perCase int) [][]byte {
	rng := rand.New(rand.NewSource(seed))
	var vectors [][]byte
	for k := 0; k < EvalOrderCases(); k++ {
		for j := 0; j < perCase; j++ {
			in := make([]byte, 128)
			rng.Read(in)
			in[0], in[1], in[2] = 0, byte(k), byte(k>>8)
			switch j % 4 {
			case 0:
				in[3] = 0
			case 1:
				in[3] = 1
			default:
				in[3] = byte(rng.Intn(64))
			}
			if in[3]&1 != 0 {
				// No nil gp or gq with panicking writers: gc's optimizer
				// may move an inlined nil dereference's fault past a later
				// inlined panic, so their relative order is not gc's
				// order pass (docs/ERROR_CONTRACT.md#evaluation-order).
				in[3] &^= 4 | 8
			}
			vectors = append(vectors, in)
		}
	}
	return vectors
}

// EvalOrderVectorsForTest is the vector set the SBF test runs.
func EvalOrderVectorsForTest() [][]byte { return evalOrderVectors(20261015, 3) }

// nativeEvalOrderCall runs Run natively: the result and output, or the
// panic's log line (hex, as the driver prints it) and the output.
func nativeEvalOrderCall(in []byte) (result string, line string) {
	out := make([]byte, 1024)
	defer func() {
		if r := recover(); r != nil {
			line = ExpectedPanicLine(r, "evalorder")
			prefix := ""
			if line != "" {
				prefix = "L:" + hex.EncodeToString([]byte(line)) + " "
			}
			result = fmt.Sprintf("%sP:%x\n", prefix, out)
		}
	}()
	code := evalorder.Run(out, append([]byte(nil), in...))
	return fmt.Sprintf("%d:%x\n", code, out), ""
}

func compileEvalOrder(t *testing.T) []byte {
	t.Helper()
	c, err := CompileProgram(&Program{Entry: "program", Packages: []PackageSources{{"program", []Source{{Name: "program.go", Data: evalOrderSource(t)}}}}})
	if err != nil {
		t.Fatal(err)
	}
	return c
}

func TestEvalOrderDifferential(t *testing.T) {
	t.Parallel()
	bin := hostCompile(t, compileEvalOrder(t), DefaultHeapBytes, valueTypesDriver, false)
	vectors := evalOrderVectors(20261015, 6)
	var want []string
	var got strings.Builder
	var batch strings.Builder
	flush := func() {
		if batch.Len() > 0 {
			got.WriteString(runHost(t, bin, batch.String()))
			batch.Reset()
		}
	}
	panics, logged := 0, 0
	for _, in := range vectors {
		line := fmt.Sprintf("%x\n", in)
		result, logLine := nativeEvalOrderCall(in)
		want = append(want, result)
		if strings.Contains(result, "P:") {
			panics++
			if logLine != "" {
				logged++
			}
			flush()
			got.WriteString(runHost(t, bin, line))
			continue
		}
		batch.WriteString(line)
	}
	flush()
	gotLines := strings.SplitAfter(got.String(), "\n")
	for j := range want {
		if j >= len(gotLines) || gotLines[j] != want[j] {
			g := ""
			if j < len(gotLines) {
				g = gotLines[j]
			}
			t.Fatalf("vector %d (case %d, %x):\nC  %.300q\nGo %.300q", j, int(vectors[j][1])|int(vectors[j][2])<<8, vectors[j], g, want[j])
		}
	}
	if panics == 0 || logged == 0 || logged == panics {
		t.Fatalf("%d panics (%d logged): the vectors must exercise traps and logged panics", panics, logged)
	}
	t.Logf("%d vectors over %d cases (%d aborts, %d with a panic line) match native Go", len(vectors), EvalOrderCases(), panics, logged)
}
